#include <set>
#include <functional>
#include <iostream>

int main() {
    // Define a set using std::greater<int> for descending order
    typedef std::set<int, std::greater<int>> IntSetDesc;
    IntSetDesc coll1;

    coll1.insert(4);
    coll1.insert(1);
    coll1.insert(5);

    // Output will be 5, 4, 1 (descending)
    for (int elem : coll1) {
        std::cout << elem << ' ';
    }
    std::cout << '\n';
}
